<?php declare(strict_types=1);$e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$components=dirname(__DIR__,2).'/components';ob_start();$breadcrumbItems=[['label'=>'Dashboard','url'=>'/dashboard'],['label'=>'Corporate','url'=>'/dashboard'],['label'=>'Application Reviews','current'=>true]];require $components.'/breadcrumb.php';$heading='Application Reviews';$description='Review prospect submissions from all communities.';$eyebrow='Corporate';$actionsHtml='';require $components.'/page-header.php';?><div class="gateway-review-summary d-flex flex-wrap gap-2" role="status" aria-label="Application Review status summary"><?php foreach([['pending_review','Pending Review','neutral'],['approved','Approved','success'],['denied','Denied','danger']] as [$key,$label,$type]):$statusLabel=$counts[$key].' '.$label;$statusType=$type;require $components.'/status-badge.php';endforeach;?></div><form class="gateway-filter-bar" method="get" action="/corporate/application-reviews"><label>Employee or prospect<input class="form-control" type="search" name="search" value="<?=$e($search)?>"></label><label>Status<select class="form-select" name="status"><option value="">All statuses</option><?php foreach(['pending_review'=>'Pending Review','approved'=>'Approved','denied'=>'Denied'] as $value=>$label):?><option value="<?=$value?>"<?=$status===$value?' selected':''?>><?=$label?></option><?php endforeach;?></select></label><label>Property<select class="form-select" name="property"><option value="">All properties</option><?php foreach($properties as $property):?><option value="<?=$e($property['public_id'])?>"<?=$propertyPublicId===$property['public_id']?' selected':''?>><?=$e($property['display_name'])?></option><?php endforeach;?></select></label><button class="btn btn-secondary" type="submit">Apply Filters</button></form><?php if($reviews===[]):$emptyTitle='No application reviews';$emptyMessage='No records match the selected filters.';$emptyIconHtml='';$emptyActionHtml='';require $components.'/empty-state.php';else:?><div class="table-responsive"><table class="table gateway-directory-table"><thead><tr><th scope="col">Prospect</th><th scope="col">Property</th><th scope="col">Submitted By</th><th scope="col">Submitted</th><th scope="col">Status</th><th scope="col">Reviewed</th><th scope="col">Action</th></tr></thead><tbody><?php foreach($reviews as $review):?><tr><td><?=$e($review['prospect_name'])?></td><td><?=$e($review['property_name'])?></td><td><?=$e($review['submitted_by_name'])?></td><td><?=$e((new DateTimeImmutable($review['submitted_at']))->format('F j, Y \a\t g:i A'))?></td><td><?php $statusLabel=['pending_review'=>'Pending Review','approved'=>'Approved','denied'=>'Denied'][$review['status']];$statusType=['pending_review'=>'neutral','approved'=>'success','denied'=>'danger'][$review['status']];require $components.'/status-badge.php';?></td><td><?=$review['reviewed_at']?$e((new DateTimeImmutable($review['reviewed_at']))->format('F j, Y \a\t g:i A')):'—'?></td><td><?php if($review['status']==='pending_review'):?><a class="btn btn-sm btn-outline-primary" href="/corporate/application-reviews/<?=$e($review['public_id'])?>">Review</a><?php else:?><a href="/corporate/application-reviews/<?=$e($review['public_id'])?>">View</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;$contentHtml=(string)ob_get_clean();$pageTitle='Application Reviews — NPM Gateway';$navbarItems=\NpmGateway\Support\Navigation::forRoute('/corporate/application-reviews',dirname(__DIR__,4));$navbarUserLabel=$user->displayName;$navbarUserContext='@'.$user->username;require dirname(__DIR__,2).'/layouts/app.php';
